mapper.update:
UPDATE
       TB_CAR
   SET
       CAR_NAME = #{carName}
     , CAR_PLATE = #{carPlate}
     , MAX_PASSENGER = #{maxPassenger}
     , COLOR = #{color}
     , CAR_LOCATION = #{carLocation}
     , CAR_BRAND = #{carBrand}
 WHERE
       CAR_NO = #{carNo}
   AND
       STATUS = 'Y'

UPDATE
       TB_CAR_IMG
   SET
       ORIGIN_NAME = #{originName}
     , CHANGE_NAME = #{changeName}
 WHERE
       CAR_NO = #{carNo}
   AND
       STATUS = 'Y'

UPDATE
       TB_CAR_FILE
   SET
       ORIGIN_NAME = #{originName}
     , CHANGE_NAME = #{changeName}
 WHERE
       CAR_NO = #{carNo}
   AND
       STATUS = 'Y'
